  ('f6bacfd0-b6a8-4b76-a20a-0332e7a18f1e', 'darien', DATE '2025-11-18', null, 'Report is '),
  ('8115b344-3e85-4c73-9b88-31a52e0861d2', 'darien', DATE '2025-11-02', null, 'Red Polsih: Increased VD to bring us closer to target usage and improve show. Wax; Increased Vd to 9 to bring us closer to target. '),
  ('09826a43-59ec-43f1-bd22-44d00ef4ead5', 'darien', DATE '2025-12-16', null, null),
  ('dfc519dc-90f9-49f3-8b8f-cd6f1037d859', 'darien', DATE '2026-01-13', null, null),
