  ('eb797028-70d8-4a7f-99a4-6f040d1ed601', 'darien', DATE '2026-02-13', null, null),
  ('9c6a2666-5802-454b-9b97-889b5e3aa3da', 'darien', DATE '2026-02-20', null, 'Rainy day, no cars being washed. FWW- High usage. Lowered Vd from 17 to 12. '),
  ('48ca68e0-c546-4406-8a65-66b6b1c4be16', 'darien', DATE '2026-03-12', null, null),
  ('db1dd76f-e5ea-4eb4-97c9-edc8e956bcab', 'darien', DATE '2026-03-26', null, null),
