  ('90444000-5e73-4184-812f-0b2d5aff617b', 'rensselear', DATE '2025-11-14', null, 'First Foamer: High usage. Cleaned versadial filter. Versadial would not allow me to make small incremental adj. Replaced Versadail. Set VD at 24. Using 7mls. '),
  ('49f2d40b-2f94-4b56-9880-7d0702b446c2', 'rensselear', DATE '2025-12-11', null, 'Presoak: Application was not applying to the car-low pressure. Found dirty generator, told managment to include presoak in routine cleaning in order to prevent build up again. Application normal again after cleaning. Increased Thumb gun to 1:50 to bring us closer to target. '),
  ('f801338e-cc16-4963-9b40-b9b94b7e5225', 'rensselear', DATE '2025-12-19', null, 'Presoak: Application was not applying to the car-low pressure. Found dirty generator, told managment to include presoak in routine cleaning in order to prevent build up again. Application normal again after cleaning. '),
